#!/usr/bin/env python3
import argparse, hashlib, json, os, re, stat, sys, tarfile, time, zipfile
from collections import Counter, defaultdict
from pathlib import Path

EXCLUDED = set()
TEXT_LIMIT = 8 * 1024 * 1024
HASH_LIMIT = 512 * 1024 * 1024
ARCHIVE_LIMIT = 256 * 1024 * 1024
GO_EXTENSIONS = {'.go'}
ARCHIVE_EXTENSIONS = {'.zip', '.jar', '.tar', '.tgz', '.gz', '.bz2', '.xz'}
META_NAMES = {'go.mod', 'go.sum', 'go.work', 'go.work.sum', 'vendor.json'}
GO_MARKERS = [b'package ', b'import ', b'func ', b'type ', b'go:build', b'// +build', b'go:generate', b'go:linkname']
PACKAGE_RE = re.compile(rb'(?m)^\s*package\s+[A-Za-z_][A-Za-z0-9_]*\s*(?://.*)?$')
IMPORT_RE = re.compile(rb'(?m)^\s*import(?:\s|\(|$)')
FUNC_RE = re.compile(rb'(?m)^\s*func(?:\s|\(|\*)')
TYPE_RE = re.compile(rb'(?m)^\s*type\s+[A-Za-z_][A-Za-z0-9_]*\s')


def is_excluded(path):
    p = '/' + path.lstrip('/')
    return any(p == x or p.startswith(x + '/') for x in EXCLUDED)


def sha256_file(path):
    h = hashlib.sha256()
    with open(path, 'rb', buffering=1024 * 1024) as f:
        while True:
            b = f.read(1024 * 1024)
            if not b:
                break
            h.update(b)
    return h.hexdigest()


def classify_content(data):
    if b'\x00' in data[:65536]:
        return None
    try:
        data.decode('utf-8')
    except UnicodeDecodeError:
        return None
    package = bool(PACKAGE_RE.search(data))
    imports = bool(IMPORT_RE.search(data))
    funcs = bool(FUNC_RE.search(data))
    types = bool(TYPE_RE.search(data))
    markers = [m.decode('ascii') for m in GO_MARKERS if m in data]
    score = (4 if package else 0) + (2 if imports else 0) + (1 if funcs else 0) + (1 if types else 0) + min(2, len(markers))
    if package and score >= 6:
        return 'confirmed Go source', score, markers
    if package and score >= 4:
        return 'probable Go source', score, markers
    if score >= 4 and (b'package' in data or b'go:' in data):
        return 'probable Go source', score, markers
    return None


def archive_members(path, errors):
    out = []
    try:
        size = os.path.getsize(path)
        if size > ARCHIVE_LIMIT:
            return out
        suffix = path.lower()
        if suffix.endswith(('.zip', '.jar')):
            with zipfile.ZipFile(path) as z:
                for info in z.infolist():
                    name = info.filename
                    if name.lower().endswith('.go'):
                        out.append({'member': name, 'size': info.file_size, 'source': 'archive-member-extension'})
                    elif info.file_size <= TEXT_LIMIT:
                        try:
                            data = z.read(info)
                            c = classify_content(data)
                            if c:
                                out.append({'member': name, 'size': info.file_size, 'source': 'archive-member-content', 'classification': c[0], 'score': c[1], 'markers': c[2]})
                        except Exception as e:
                            errors.append({'path': f'{path}!{name}', 'error': str(e)})
        elif suffix.endswith(('.tar', '.tgz', '.tar.gz', '.tar.bz2', '.tar.xz')):
            with tarfile.open(path, 'r:*') as t:
                for info in t:
                    if not info.isfile():
                        continue
                    name = info.name
                    if name.lower().endswith('.go'):
                        out.append({'member': name, 'size': info.size, 'source': 'archive-member-extension'})
                    elif info.size <= TEXT_LIMIT:
                        try:
                            f = t.extractfile(info)
                            data = f.read(TEXT_LIMIT + 1) if f else b''
                            c = classify_content(data)
                            if c:
                                out.append({'member': name, 'size': info.size, 'source': 'archive-member-content', 'classification': c[0], 'score': c[1], 'markers': c[2]})
                        except Exception as e:
                            errors.append({'path': f'{path}!{name}', 'error': str(e)})
    except Exception as e:
        errors.append({'path': path, 'error': f'archive: {e}'})
    return out


def scan(root, out_dir):
    started = time.time()
    records, errors, archives = [], [], []
    counts = Counter()
    seen_inodes = {}
    stack = [os.path.abspath(root)]
    visited_dirs = set()
    while stack:
        d = stack.pop()
        if is_excluded(d):
            counts['excluded_directories'] += 1
            continue
        try:
            ds = os.scandir(d)
        except OSError as e:
            errors.append({'path': d, 'error': str(e)})
            counts['inaccessible_directories'] += 1
            continue
        with ds:
            try:
                dst = os.stat(d, follow_symlinks=False)
                dkey = (dst.st_dev, dst.st_ino)
                if dkey in visited_dirs:
                    continue
                visited_dirs.add(dkey)
            except OSError:
                pass
            for ent in ds:
                p = ent.path
                try:
                    st = ent.stat(follow_symlinks=False)
                except OSError as e:
                    errors.append({'path': p, 'error': str(e)})
                    counts['inaccessible_entries'] += 1
                    continue
                mode = st.st_mode
                if stat.S_ISDIR(mode):
                    if not is_excluded(p):
                        stack.append(p)
                    continue
                if stat.S_ISLNK(mode):
                    try:
                        target = os.path.realpath(p)
                        rec = {'path': p, 'kind': 'symlink', 'target': target}
                        if os.path.isfile(target):
                            rec['evidence'] = 'symlink-to-regular-file'
                        records.append(rec)
                    except OSError as e:
                        errors.append({'path': p, 'error': str(e)})
                    continue
                if not stat.S_ISREG(mode):
                    kind = ('directory' if stat.S_ISDIR(mode) else 'fifo' if stat.S_ISFIFO(mode) else 'socket' if stat.S_ISSOCK(mode) else 'character-device' if stat.S_ISCHR(mode) else 'block-device' if stat.S_ISBLK(mode) else 'special')
                    rec = {'path': p, 'kind': kind, 'mode': stat.filemode(mode), 'size': st.st_size, 'mtime_ns': st.st_mtime_ns, 'device': st.st_dev, 'inode': st.st_ino, 'classification': 'special filesystem object', 'content_read': False}
                    if stat.S_ISCHR(mode) or stat.S_ISBLK(mode):
                        rec['rdev'] = st.st_rdev
                    records.append(rec)
                    counts['special_files_recorded'] += 1
                    continue
                counts['regular_files_seen'] += 1
                suffix = Path(p).suffix.lower()
                base = os.path.basename(p)
                rec = {'path': p, 'kind': 'regular', 'size': st.st_size, 'mtime_ns': st.st_mtime_ns, 'device': st.st_dev, 'inode': st.st_ino, 'evidence': []}
                key = (st.st_dev, st.st_ino)
                if key in seen_inodes:
                    rec['hardlink_to'] = seen_inodes[key]
                else:
                    seen_inodes[key] = p
                if suffix in GO_EXTENSIONS:
                    rec['evidence'].append('go-extension')
                if base in META_NAMES or base.startswith('go.'): 
                    rec['evidence'].append('go-tooling-metadata-name')
                if suffix in ARCHIVE_EXTENSIONS or base.endswith(('.tar.gz', '.tar.bz2', '.tar.xz')):
                    members = archive_members(p, errors)
                    if members:
                        rec['archive_members'] = members
                        archives.append(p)
                        rec['evidence'].append('archive-contains-go-like-member')
                inspect = suffix in GO_EXTENSIONS or st.st_size <= TEXT_LIMIT or any(x in p for x in ('/go/pkg/mod/', '/vendor/', '/src/', '/workspace/', '/work/'))
                if inspect and st.st_size <= TEXT_LIMIT:
                    try:
                        with open(p, 'rb') as f:
                            data = f.read(TEXT_LIMIT + 1)
                        c = classify_content(data)
                        if c:
                            rec['content_classification'], rec['content_score'], rec['content_markers'] = c
                            rec['evidence'].append('Go-lexical-content')
                    except (OSError, UnicodeError) as e:
                        errors.append({'path': p, 'error': str(e)})
                if rec['evidence'] or rec.get('content_classification'):
                    if rec.get('content_classification'):
                        rec['classification'] = rec['content_classification']
                    elif 'go-extension' in rec['evidence']:
                        rec['classification'] = 'probable Go source'
                    elif 'archive-contains-go-like-member' in rec['evidence'] or 'go-tooling-metadata-name' in rec['evidence']:
                        rec['classification'] = 'Go-related artifact'
                    records.append(rec)
    # Hash only candidate regular files, streaming and bounded.
    for rec in records:
        if rec.get('kind') != 'regular' or rec.get('size', 0) > HASH_LIMIT:
            continue
        try:
            rec['sha256'] = sha256_file(rec['path'])
        except OSError as e:
            errors.append({'path': rec['path'], 'error': f'hash: {e}'})
    records.sort(key=lambda r: r.get('path', ''))
    out_dir = os.path.abspath(out_dir)
    os.makedirs(out_dir, exist_ok=True)
    inventory = os.path.join(out_dir, 'go_inventory.jsonl')
    with open(inventory, 'w', encoding='utf-8') as f:
        for rec in records:
            f.write(json.dumps(rec, ensure_ascii=False, sort_keys=True) + '\n')
    error_file = os.path.join(out_dir, 'scan_errors.jsonl')
    with open(error_file, 'w', encoding='utf-8') as f:
        for err in errors:
            f.write(json.dumps(err, ensure_ascii=False, sort_keys=True) + '\n')
    class_counts = Counter(r.get('classification', 'unclassified') for r in records)
    summary = {
        'started_epoch': started, 'finished_epoch': time.time(), 'root': os.path.abspath(root),
        'excluded_roots': sorted(EXCLUDED), 'records': len(records), 'classification_counts': dict(class_counts),
        'scan_counts': dict(counts), 'errors': len(errors), 'archive_containers_with_go_members': len(set(archives)),
        'unique_sha256': len({r['sha256'] for r in records if 'sha256' in r}),
        'hardlink_aliases': sum(1 for r in records if 'hardlink_to' in r),
        'notes': ['Read-only scan.', 'All mounted paths are traversed, including pseudo-filesystems.', 'Only regular files are opened; device, socket, FIFO, and other special files are skipped.', 'No privilege escalation attempted.', 'Content classifier is heuristic and evidence is retained.']
    }
    with open(os.path.join(out_dir, 'scan_summary.json'), 'w', encoding='utf-8') as f:
        json.dump(summary, f, indent=2, sort_keys=True)
    return summary


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--root', default='/')
    ap.add_argument('--out', required=True)
    args = ap.parse_args()
    print(json.dumps(scan(args.root, args.out), indent=2, sort_keys=True))

if __name__ == '__main__':
    main()


